use std::{cmp, env};

use crate::constants;
use std::collections::HashMap;

use chrono::{DateTime, Duration, Local, Utc};
use colored::{ColoredString, Colorize};
use colors_transform::{Color, Rgb};
use lazy_static::lazy_static;
use serde::{Deserialize, Serialize};

pub type ResultWithDefaultError<T> = Result<T, Box<dyn std::error::Error + Send>>;

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Tag {
    pub id: i64,
    pub name: String,
    pub workspace_id: i64,
}

impl std::fmt::Display for Tag {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.name)
    }
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Entities {
    pub time_entries: Vec<TimeEntry>,
    pub projects: HashMap<i64, Project>,
    pub tasks: HashMap<i64, Task>,
    pub clients: HashMap<i64, Client>,
    pub workspaces: Vec<Workspace>,
    pub tags: Vec<Tag>,
}

impl Entities {
    pub fn workspace_id_for_name(&self, name: &str) -> Option<i64> {
        self.workspaces
            .iter()
            .find(|w| w.name == name)
            .map(|w| w.id)
    }
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct User {
    pub api_token: String,
    pub email: String,
    pub fullname: Option<String>,
    pub timezone: String,
    pub default_workspace_id: i64,
    #[serde(default)]
    pub beginning_of_week: Option<i32>,
    #[serde(default)]
    pub image_url: Option<String>,
    #[serde(default)]
    pub created_at: Option<String>,
    #[serde(default)]
    pub updated_at: Option<String>,
    #[serde(default)]
    pub country_id: Option<i64>,
    #[serde(default)]
    pub has_password: Option<bool>,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct TimeEntry {
    pub id: i64,
    pub description: String,
    pub start: DateTime<Utc>,
    pub stop: Option<DateTime<Utc>>,
    pub duration: i64,
    pub billable: bool,
    #[serde(skip_serializing)]
    pub workspace_id: i64,
    pub tags: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project: Option<Project>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub task: Option<Task>,
    #[serde(skip_serializing)]
    pub created_with: Option<String>,
}

#[allow(dead_code)]
#[derive(Serialize, Deserialize, Clone, Debug)]
