}

#[derive(Subcommand, Debug)]
pub enum EntryAction {
    /// Show the currently running time entry.
    #[command(
        name = "running",
        alias = "current",
        after_long_help = "\
Examples:
  toggl entry running             Show the running entry
  toggl entry running --json      Show the running entry as JSON

Note: JSON output includes a \"running\": true field for active entries."
    )]
    Current {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// List time entries.
    #[command(after_long_help = "\
Examples:
  toggl entry list
  toggl entry list --since today
  toggl entry list --since yesterday --until today
  toggl entry list --since 2024-01-01 --number 5
  toggl entry list --json | jq '.[].description'")]
    List {
        #[arg(short, long, help = "Maximum number of items to print")]
        number: Option<usize>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
        #[arg(
            long,
            help = "Filter time entries starting on or after this date/time (now, today, yesterday, this_week, last_week, YYYY-MM-DD, or full datetime)"
        )]
        since: Option<String>,
        #[arg(
            long,
            help = "Filter time entries before this date/time (now, today, yesterday, this_week, last_week, YYYY-MM-DD, or full datetime)"
        )]
        until: Option<String>,
    },
    /// Stop the currently running time entry.
    #[command(after_long_help = "\
Examples:
  toggl entry stop                Stop the running entry
  toggl entry stop --json         Stop and output as JSON")]
    Stop {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Start a new time entry (runs immediately with no prompt when called without arguments).
    #[command(after_long_help = "\
Examples:
  toggl entry start -d \"Writing docs\" -p MyProject
  toggl entry start -d \"Meeting\" --start 09:00 --end 10:00
  toggl entry start --json")]
    Start {
        #[arg(short, long, help = "Description of the time entry")]
        description: Option<String>,
        #[arg(
            short,
            long,
            help = "Exact name of the project you want the time entry to be associated with"
        )]
        project: Option<String>,
        #[arg(
            long,
            help = "Exact name of the task you want the time entry to be associated with"
        )]
        task: Option<String>,
        #[arg(short, long, help = "Tag name (repeatable), e.g. -t tag1 -t tag2")]
        tags: Option<Vec<String>>,
        #[arg(short, long, help = "Mark the time entry as billable")]
        billable: bool,
        #[arg(
            long,
            help = "Start date/time. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        start: Option<String>,
        #[arg(
            long,
            help = "End date/time. Requires --start. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        end: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Continue a previous time entry.
    #[command(
        name = "continue",
        alias = "resume",
        after_long_help = "\
Examples:
  toggl entry continue              Continue most recent entry
  toggl entry continue --id 12345   Continue a specific entry by ID
  toggl entry continue --json       Continue and output as JSON"
    )]
    Resume {
        #[arg(short, long, help = "Continue a specific time entry by its ID")]
        id: Option<i64>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Show details of a single time entry by ID or the currently running entry.
    #[command(after_long_help = "\
Examples:
  toggl entry show 12345
  toggl entry show 12345 --json
  toggl entry show --current
  toggl entry running        (alternative for running entry)")]
    Show {
        #[arg(help = "ID of the time entry to show")]
        id: Option<i64>,
        #[arg(short, long, help = "Show the currently running time entry")]
        current: bool,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Edit a time entry's description, billable state, project, task, or tags.
    #[command(
        name = "edit",
        alias = "update",
        after_long_help = "\
Examples:
  toggl entry edit --current -d \"New description\"
  toggl entry edit 12345 -p NewProject
  toggl entry edit 12345 --end \"\"     # Re-open a stopped entry
  toggl entry edit 12345 -p \"\"        # Remove project from entry"
    )]
    Update {
        #[arg(help = "ID of the time entry to edit")]
        id: Option<i64>,
        #[arg(short, long, help = "Edit the currently running time entry")]
        current: bool,
        #[arg(short, long, help = "New description")]
        description: Option<String>,
        #[arg(long, help = "New billable state (true/false)")]
        billable: Option<bool>,
        #[arg(
            short,
            long,
            help = "New project name (use empty string \"\" to remove project)"
        )]
        project: Option<String>,
        #[arg(long, help = "New task name (use empty string \"\" to remove task)")]
        task: Option<String>,
        #[arg(
            short,
            long,
            help = "Tag name (repeatable, use empty string \"\" to clear tags), e.g. -t tag1 -t tag2"
        )]
        tags: Option<Vec<String>>,
        #[arg(
            long,
            help = "New start date/time. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        start: Option<String>,
        #[arg(
            long,
            help = "New end date/time (use empty string \"\" to clear end time). Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        end: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Delete a time entry by ID.
    #[command(after_long_help = "\
Examples:
  toggl entry delete 12345
  toggl entry delete --current
  toggl entry delete 12345 --json")]
    Delete {
        #[arg(help = "ID of the time entry to delete")]
        id: Option<i64>,
        #[arg(short, long, help = "Delete the currently running time entry")]
) -> ResultWithDefaultError<()> {
    // Validate required arguments BEFORE creating the API client to avoid
    // unnecessary keychain/storage access for validation failures.
    match &action {
        EntryAction::Show { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'show' requires an entry ID or --current flag. Run `toggl entry list` or `toggl entry running` to find one.".to_string(),
            )));
        }
        EntryAction::Update { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'edit' requires an entry ID or --current flag. Example: toggl entry edit --current -d \"New description\"".to_string(),
            )));
        }
        EntryAction::Update {
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            ..
        } if description.is_none()
            && billable.is_none()
            && project.is_none()
            && task.is_none()
            && tags.is_none()
            && start.is_none()
            && end.is_none() =>
        {
            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
            )));
        }
        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
            )));
        }
        EntryAction::BulkEdit { json: None, .. } => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'bulk-edit' requires --json flag with JSON payload".to_string(),
            )));
        }
        _ => {}
    }

    let api_client = get_api_client(proxy.clone())?;

    match action {
        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
        EntryAction::List {
            number,
            json,
            since,
            until,
        } => ListCommand::execute(api_client, number, json, since, until, None).await,
        EntryAction::Stop { json } => {
            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
            Ok(())
        }
        EntryAction::Start {
            billable,
            description,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            StartCommand::execute(
                api_client,
                picker,
                description,
                project,
                task,
                tags,
                billable,
                false,
                start,
                end,
                json,
            )
            .await
        }
        EntryAction::Resume { id, json } => {
            ContinueCommand::execute(api_client, None, id, json).await
        }
        EntryAction::Show { id, current, json } => {
            if current {
                // Get the current running entry and show it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => ShowCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                ShowCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Update {
            id,
            current,
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            if current {
                // Check if there's a running entry before attempting edit
                match api_client.get_current_time_entry_minimal().await? {
                    Some(_) => {
                        // There's a running entry, let EditCommand handle it with id=None
                        EditCommand::execute(
                            api_client,
                            None,
                            description,
                            billable,
                            project,
                            task,
                            tags,
                            start,
                            end,
                            json,
                        )
                        .await
                    }
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                EditCommand::execute(
                    api_client,
                    id,
                    description,
                    billable,
                    project,
                    task,
                    tags,
                    start,
                    end,
                    json,
                )
                .await
            }
        }
        EntryAction::Delete { id, current, json } => {
            if current {
                // Get the current running entry and delete it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => DeleteCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                DeleteCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Search {
            query,
            project,
            no_project,
            tags,
            no_tag,
            since,
            until,
            number,
            order_by,
            order_dir,
            json,
        } => {
            commands::search::execute(
                api_client, query, project, no_project, tags, no_tag, since, until, number,
                order_by, order_dir, json,
            )
            .await
        }
        EntryAction::BulkEdit { ids, json } => {
            // json is guaranteed Some due to validation above
            BulkEditTimeEntriesCommand::execute(api_client, ids.clone(), json.clone().unwrap())

    async fn stop_time_entry(
        &self,
        workspace_id: i64,
        time_entry_id: i64,
    ) -> ResultWithDefaultError<TimeEntry> {
        let url = format!(
            "{}/workspaces/{}/time_entries/{}/stop",
            self.base_url, workspace_id, time_entry_id
        );
        let network_entry = self.patch_without_body::<NetworkTimeEntry>(url).await?;
        Ok(self.hydrate_single_network_entry(network_entry).await)
    }

    async fn bulk_update_time_entries(
        &self,
        workspace_id: i64,
        time_entry_ids: Vec<i64>,
        patch: Value,
    ) -> ResultWithDefaultError<Value> {
        let ids = time_entry_ids
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

    async fn get_time_entries_filtered(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let (network_entries, network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_time_entries(since.as_deref(), until.as_deref()),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .into_iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name,
                        workspace_id: c.wid,
                        archived: c.archived,
                    },
                )
            })
            .collect();

        let projects: HashMap<i64, Project> = network_projects
            .unwrap_or_default()
            .into_iter()
            .map(|p| {
                (
                    p.id,
                    Project {
                        id: p.id,
                        name: p.name.clone(),
                        workspace_id: p.workspace_id,
                        client: clients.get(&p.client_id.unwrap_or(-1)).cloned(),
                        is_private: p.is_private,
                        active: p.active,
                        at: p.at,
                        created_at: p.created_at,
                        color: p.color,
                        billable: p.billable,
                    },
                )
            })
            .collect();

        let tasks: HashMap<i64, Task> = network_tasks
            .unwrap_or_default()
            .into_iter()
            .filter_map(|t| {
                projects.get(&t.project_id).map(|project| {
                    (
                        t.id,
                        Task {
                            id: t.id,
                            name: t.name,
                            project: project.clone(),
                            workspace_id: t.workspace_id,
                            active: t.active.unwrap_or(true),
                        },
                    )
                })
            })
            .collect();

        let entries = network_entries?
            .into_iter()
            .map(|te| TimeEntry {
                id: te.id,
                description: te.description,
                start: te.start,
                stop: te.stop,
                duration: te.duration,
                billable: te.billable,
                workspace_id: te.workspace_id,
                tags: te.tags.unwrap_or_default(),
                project: projects.get(&te.project_id.unwrap_or(-1)).cloned(),
                task: tasks.get(&te.task_id.unwrap_or(-1)).cloned(),
                ..Default::default()
            })
            .collect();

        Ok(entries)
    }

    async fn get_time_entries_filtered_minimal(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let network_entries = self
            .get_time_entries(since.as_deref(), until.as_deref())
